   while q:
    a,b=q.pop(); pts.append((a,b))
    for v in ((a-1,b),(a+1,b),(a,b-1),(a,b+1)):
     if 0<=v[0]<H and 0<=v[1]<W and grid[v[0]][v[1]]==color and v not in seen:
      seen.add(v); q.append(v)
   rr=[x for x,y in pts]; cc=[y for x,y in pts]
   comps.append((len(pts),(min(rr),max(rr),min(cc),max(cc)),sorted(pts)))
